# This code has been fully generated by an AI.
"""Arena: vier Ecken, Entzerrung zum Rechteck und Roboter-Erkennung gegen den einfarbigen Boden."""

import cv2
import numpy as np

# Längere Arenaseite in Arena-Einheiten. Fest, damit Spielwerte nicht von Kamera und Auflösung abhängen.
UNITS = 1000.0
# Boden ist einfarbig; Werte gemessen an echten Bildern (OpenCV-Lab, 8 Bit).
COLOUR_DIST = 7.0
# Schatten dunkeln den Boden auf etwa 0,8 ab; Roboterteile wie Reifen liegen weit darunter.
DARK_RATIO = 0.6
TEXTURE_SD = 10.0
# Fenster und Verschmelzung relativ zur längeren Bildseite, damit es bei jeder Auflösung gleich wirkt.
TEXTURE_WINDOW = 0.014
MERGE = 0.03
# Randstreifen ignorieren: geklickte Ecken liegen auf Arenalinie oder Bande, die sonst als Ring alles f?llen.
EDGE = 0.012
# Kleinere Flecken sind Krümel oder Rauschen.
MIN_AREA = 0.003
# Weißer Hintergrund fürs Modell: so viel Rand um den Vordergrund bleibt echt, so weich ist der Übergang.
KEEP_PX = 12
FEATHER_PX = 4


def order_corners(points) -> np.ndarray:
    """Sortiert vier Punkte zu oben-links, oben-rechts, unten-rechts, unten-links."""
    pts = np.asarray(points, dtype=np.float32).reshape(4, 2)
    # Nach Winkel um den Schwerpunkt sortieren, damit beliebige Klickreihenfolgen funktionieren.
    center = pts.mean(axis=0)
    pts = pts[np.argsort(np.arctan2(pts[:, 1] - center[1], pts[:, 0] - center[0]))]
    return np.roll(pts, -int(np.argmin(pts.sum(axis=1))), axis=0)


class Arena:
    """Viereck im Kamerabild, entzerrt auf ein Rechteck mit der längeren Seite UNITS."""

    def __init__(self, corners):
        self.corners = order_corners(corners)
        tl, tr, br, bl = self.corners
        # Seitenverhältnis aus den längeren gegenüberliegenden Kanten, wie bei der Vier-Punkt-Entzerrung.
        w = max(np.linalg.norm(tr - tl), np.linalg.norm(br - bl))
        h = max(np.linalg.norm(bl - tl), np.linalg.norm(br - tr))
        if cv2.contourArea(self.corners) < 100 or min(w, h) < 10:
            raise ValueError("Die vier Ecken spannen keine Fläche auf.")
        k = UNITS / max(w, h)
        self.size = (float(w * k), float(h * k))
        self.extent = float(max(w, h))
        W, H = self.size
        dst = np.array([[0, 0], [W, 0], [W, H], [0, H]], np.float32)
        self.h = cv2.getPerspectiveTransform(self.corners, dst)

    def matrix(self, px_per_unit: float) -> np.ndarray:
        return np.diag([px_per_unit, px_per_unit, 1.0]) @ self.h

    def pixels(self, px_per_unit: float) -> tuple[int, int]:
        return max(1, round(self.size[0] * px_per_unit)), max(1, round(self.size[1] * px_per_unit))

    def warp(self, image: np.ndarray, px_per_unit: float, pad: float = 0.0) -> np.ndarray:
        """Entzerrte Draufsicht; `pad` Arena-Einheiten Rand ringsum zeigen zusätzlich die Umgebung."""
        m = np.array([[1, 0, pad], [0, 1, pad], [0, 0, 1]]) @ self.h
        size = (max(1, round((self.size[0] + 2 * pad) * px_per_unit)),
                max(1, round((self.size[1] + 2 * pad) * px_per_unit)))
        # Außerhalb des Kamerabilds schwarz statt gestreckter Randpixel; im Rand liegt ohnehin Rauch darüber.
        border = cv2.BORDER_CONSTANT if pad else cv2.BORDER_REPLICATE
        return cv2.warpPerspective(image, np.diag([px_per_unit, px_per_unit, 1.0]) @ m, size,
                                   flags=cv2.INTER_LINEAR, borderMode=border)


def _odd(n: float) -> int:
    return max(3, int(n) | 1)


def cues(view: np.ndarray) -> np.ndarray:
    """Pixel, die nicht nach Boden aussehen; Schatten zählen nicht."""
    lab = cv2.cvtColor(cv2.GaussianBlur(view, (5, 5), 0), cv2.COLOR_BGR2LAB).astype(np.float32)
    lum = lab[..., 0]
    # Der Boden bedeckt den größten Teil, also ist seine Farbe der Median; ein Leerbild braucht es nicht.
    sub = lab[::4, ::4].reshape(-1, 3)
    l0, a0, b0 = np.median(sub, axis=0)
    colour = np.hypot(lab[..., 1] - a0, lab[..., 2] - b0) > COLOUR_DIST
    dark = lum < DARK_RATIO * l0
    win = _odd(TEXTURE_WINDOW * max(view.shape[:2]))
    mean = cv2.blur(lum, (win, win))
    sd = np.sqrt(np.maximum(cv2.blur(lum * lum, (win, win)) - mean * mean, 0))
    # Textur zählt nur flächig: eine einzelne Kante (Schattenrand, Arenalinie) ist so schmal wie das Fenster.
    rect = cv2.getStructuringElement(cv2.MORPH_RECT, (win, win))
    texture = cv2.erode((sd > TEXTURE_SD).astype(np.uint8), rect)
    out = (colour | dark | texture.astype(bool)).astype(np.uint8)
    e = max(1, round(EDGE * max(view.shape[:2])))
    out[:e] = 0
    out[-e:] = 0
    out[:, :e] = 0
    out[:, -e:] = 0
    return out


def solid(raw: np.ndarray) -> np.ndarray:
    """Teile eines Roboters verbinden und Löcher füllen, damit jeder Roboter eine geschlossene Fläche ist."""
    size = max(raw.shape[:2])
    m = cv2.morphologyEx(raw, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)))
    merge = _odd(MERGE * size)
    m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (merge, merge)))
    contours, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    keep = [c for c in contours if cv2.contourArea(c) >= MIN_AREA * m.size]
    out = np.zeros_like(m)
    cv2.drawContours(out, keep, -1, 1, cv2.FILLED)
    return out.astype(bool)


def foreground(view: np.ndarray) -> np.ndarray:
    return solid(cues(view))


def whiten(image: np.ndarray, fg: np.ndarray) -> np.ndarray:
    """Bild fürs Modell, in dem alles außer den Robotern weiß ist."""
    # Großzügiger Rand, weil schwach abgehobene Roboterkanten sonst mit weiß würden.
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2 * KEEP_PX + 1, 2 * KEEP_PX + 1))
    keep = cv2.dilate(fg.astype(np.uint8), kernel).astype(np.float32)
    # Weicher Übergang, harte Kanten würde das Modell sonst als Objektgrenze lesen.
    soft = cv2.GaussianBlur(keep, (0, 0), FEATHER_PX)
    soft[fg] = 1.0
    soft = soft[..., None]
    return (image.astype(np.float32) * soft + 255.0 * (1.0 - soft) + 0.5).astype(np.uint8)
